// ─── File: src/main/java/com/bank/routing/demo/SolaceVsKafkaDemo.java ───
// Models Solace hierarchical broker-side routing vs Kafka flat topic + consumer filter.
package com.bank.routing.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SolaceVsKafkaDemo {

    private static final Logger log = Logger.getLogger("Routing");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<Txn> feed = List.of(
            new Txn("T1", "transaction/Mumbai/savings/small", new BigDecimal("20000")),
            new Txn("T2", "transaction/Mumbai/current/large", new BigDecimal("900000")),
            new Txn("T3", "transaction/Delhi/savings/large",  new BigDecimal("800000")),
            new Txn("T4", "transaction/Delhi/current/small",  new BigDecimal("15000"))
        );

        log.info("=== SOLACE: broker routes by hierarchy + wildcards (only matches delivered) ===");
        SolaceBroker solace = new SolaceBroker();
        solace.subscribe("mumbai-ops",   "transaction/Mumbai/>");     // > multi-level
        solace.subscribe("large-monitor","transaction/*/*/large");    // * single-level
        for (Txn t : feed) solace.publish(t);

        log.info("=== KAFKA: flat topic, every consumer gets ALL, filters itself ===");
        KafkaFlatTopic kafka = new KafkaFlatTopic();
        for (Txn t : feed) kafka.append(t);
        kafka.consumerFilter("mumbai-ops",    t -> t.topic.startsWith("transaction/Mumbai/"));
        kafka.consumerFilter("large-monitor", t -> t.topic.endsWith("/large"));
    }
}

// ─── Would be in Txn.java ───
class Txn {
    final String txnId; final String topic; final BigDecimal amount;
    Txn(String txnId, String topic, BigDecimal amount) {
        this.txnId = txnId; this.topic = topic; this.amount = amount;
    }
}

// ─── Would be in SolaceBroker.java (hierarchical matching happens in the BROKER) ───
class SolaceBroker {
    private static final Logger log = Logger.getLogger("Routing");
    private final Map<String, String> subs = new LinkedHashMap<>();   // name → pattern
    void subscribe(String name, String pattern) {
        subs.put(name, pattern);
        log.fine(() -> "subscription " + name + " = " + pattern);
    }
    void publish(Txn t) {
        for (var e : subs.entrySet()) {
            if (matches(e.getValue(), t.topic)) {         // broker evaluates the match
                log.info(() -> "broker delivered " + t.txnId + " topic=" + t.topic
                        + " -> subscriber " + e.getKey());
            }
        }
    }
    // '*' matches exactly one level; '>' matches one or more remaining levels.
    private boolean matches(String pattern, String topic) {
        String[] p = pattern.split("/");
        String[] s = topic.split("/");
        int i = 0;
        for (; i < p.length; i++) {
            if (p[i].equals(">")) return true;            // multi-level: rest matches
            if (i >= s.length) return false;
            if (p[i].equals("*")) continue;               // single-level wildcard
            if (!p[i].equals(s[i])) return false;         // literal must match
        }
        return i == s.length;                             // exact length when no '>'
    }
}

// ─── Would be in KafkaFlatTopic.java (flat; CONSUMER does the filtering) ───
class KafkaFlatTopic {
    private static final Logger log = Logger.getLogger("Routing");
    private final List<Txn> topic = new ArrayList<>();
    void append(Txn t) { topic.add(t); }
    void consumerFilter(String name, java.util.function.Predicate<Txn> wanted) {
        for (Txn t : topic) {
            // Consumer receives EVERY record, then decides. Broker did no routing.
            if (wanted.test(t)) {
                log.info(() -> "consumer " + name + " KEPT " + t.txnId + " topic=" + t.topic);
            } else {
                log.fine(() -> "consumer " + name + " discarded " + t.txnId);
            }
        }
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
